import{_ as o,o as r,c as t,aj as n}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"No hydration info in server response","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG0505.md","filePath":"en/errors/NG0505.md"}'),i={name:"en/errors/NG0505.md"};function a(s,e,d,h,c,p){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="no-hydration-info-in-server-response" tabindex="-1">No hydration info in server response <a class="header-anchor" href="#no-hydration-info-in-server-response" aria-label="Permalink to &quot;No hydration info in server response&quot;">​</a></h1><p>This error occurs when hydration is enabled on the client, but the server response doesn&#39;t contain special serialized information about the application that hydration logic relies on.</p><p>This can happen when the <code>provideClientHydration()</code> function is included in the client part of the application configuration, but is missing in the server part of the configuration.</p><p>In applications with the default project structure (generated by the <code>ng new</code>), the <code>provideClientHydration()</code> call is added either into the <code>providers</code> array of the main <code>AppModule</code> (which is imported into the server module) or into a set of providers that are included into both client and server configurations.</p><p>If you have a custom setup where client and server configuration are independent and do not share common set of providers, make sure that the <code>provideClientHydration()</code> is also included into the set of providers used to bootstrap an application on the server.</p><p>More information about hydration can be found in <a href="/en/guide/hydration">this guide</a>.</p><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>Verify that the <code>provideClientHydration()</code> call is included into a set of providers that is used to bootstrap an application on the server.</p>',8)]))}const f=o(i,[["render",a]]);export{u as __pageData,f as default};
